<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\Shop\CategoryTemplate;use Exception;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use Illuminate\Validation\ValidationException;class AddController extends BaseController{    /**     * @param Request $request     *     * @return array     * @throws ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        $result = [];        try {            $result = (new CategoryTemplate())->categoryAdd($input);            // 日志记录            $this->writeOperatorLog('删除【' . $input['id'] . '】分类');        } catch (Error $error) {            Log::info('添加分类失败', $error->data);            notice(100000, [$error->getMessage()]);        } catch (Exception $e) {            Log::info('添加分类失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($result);    }    /**     * 验证数据     * @param $request     * @return array     * @throws ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'cate_tpl_id' => 'required|integer',            'id'          => 'integer',        ];        $messages = [            'cate_tpl_id.*' => '模版分类不存在',            'id.*'          => '分类ID必须是数字',        ];        return $this->validate($request, $rule, $messages);    }}